// SPDX-License-Identifier: GPL-3.0-or-later
//! Generates `src/generated/syntaxdata.rs` from the GAMS-shipped
//! `$GAMS_SYSDIR/apifiles/C++/api/syntaxdata.h` (GPL-3.0, generated by
//! gamsoptions.py, part of the GAMS Studio project).
//!
//! Usage: `cargo run -p gams-syntax --bin gen_tables [-- <syntaxdata.h> [<out.rs>]]`
//! Defaults: `$GAMS_SYSDIR` (required unless the header is given) and the
//! committed file inside this crate.

use std::fmt::Write as _;
use std::path::PathBuf;

enum Value {
    Str(String),
    Int(i64),
}

struct Table {
    func: String,
    second_is_int: bool,
    entries: Vec<(String, Value)>,
}

/// Parses a C++ string literal starting at `s[0] == '"'`; returns (value, rest).
fn parse_cpp_string(s: &str) -> Option<(String, &str)> {
    let mut chars = s.char_indices();
    if chars.next()?.1 != '"' {
        return None;
    }
    let mut out = String::new();
    while let Some((i, c)) = chars.next() {
        match c {
            '"' => return Some((out, &s[i + 1..])),
            '\\' => {
                let (_, e) = chars.next()?;
                out.push(match e {
                    'n' => '\n',
                    't' => '\t',
                    'r' => '\r',
                    '0' => '\0',
                    other => other,
                });
            }
            c => out.push(c),
        }
    }
    None
}

fn parse_tables(src: &str) -> Vec<Table> {
    let mut tables = Vec::new();
    let mut current: Option<Table> = None;
    for line in src.lines() {
        let t = line.trim();
        if let Some(rest) = t.strip_prefix("static const QList<QPair<QString, ") {
            // e.g. `QString>> directives() {` or `int>> systemCTConstants() {`
            let second_is_int = rest.starts_with("int>>");
            let after = rest.split_once(">> ").map(|x| x.1).unwrap_or("");
            let func = after.split('(').next().unwrap_or("").trim().to_string();
            if !func.is_empty() && after.contains("()") {
                current = Some(Table {
                    func,
                    second_is_int,
                    entries: Vec::new(),
                });
            }
            continue;
        }
        if let Some(tab) = current.as_mut() {
            if t.starts_with("};") {
                tables.push(current.take().unwrap());
                continue;
            }
            if let Some(body) = t.strip_prefix('{') {
                let Some((first, rest)) = parse_cpp_string(body) else {
                    continue;
                };
                let rest = rest.trim_start().trim_start_matches(',').trim_start();
                let value = if tab.second_is_int {
                    let num: String = rest
                        .chars()
                        .take_while(|c| c.is_ascii_digit() || *c == '-')
                        .collect();
                    match num.parse() {
                        Ok(v) => Value::Int(v),
                        Err(_) => continue,
                    }
                } else {
                    match parse_cpp_string(rest) {
                        Some((v, _)) => Value::Str(v),
                        None => continue,
                    }
                };
                tab.entries.push((first, value));
            }
        }
    }
    tables
}

/// camelCase -> SCREAMING_SNAKE (`systemCTConstText` -> `SYSTEM_CT_CONST_TEXT`).
fn const_name(func: &str) -> String {
    let chars: Vec<char> = func.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && c.is_ascii_uppercase() {
            let prev = chars[i - 1];
            let next_lower = chars.get(i + 1).is_some_and(|n| n.is_ascii_lowercase());
            if prev.is_ascii_lowercase()
                || prev.is_ascii_digit()
                || (prev.is_ascii_uppercase() && next_lower)
            {
                out.push('_');
            }
        }
        out.push(c.to_ascii_uppercase());
    }
    out
}

fn main() {
    let mut args = std::env::args().skip(1);
    let input = args.next().map(PathBuf::from).unwrap_or_else(|| {
        let sysdir = std::env::var("GAMS_SYSDIR").unwrap_or_else(|_| {
            eprintln!("set GAMS_SYSDIR or pass the path of syntaxdata.h");
            std::process::exit(2)
        });
        PathBuf::from(sysdir).join("apifiles/C++/api/syntaxdata.h")
    });
    let output = args.next().map(PathBuf::from).unwrap_or_else(|| {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src/generated/syntaxdata.rs")
    });
    let src = std::fs::read_to_string(&input)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", input.display()));

    // Keep the original license/attribution header verbatim.
    let header_end = src.find("*/").map(|i| i + 2).unwrap_or(0);
    let header = &src[..header_end];

    let tables = parse_tables(&src);
    assert!(
        tables.len() >= 17,
        "expected at least 17 tables, found {}",
        tables.len()
    );

    let mut out = String::new();
    out.push_str("// @generated by `cargo run -p gams-syntax --bin gen_tables` -- DO NOT EDIT.\n");
    let _ = writeln!(out, "// Source: $GAMS_SYSDIR/apifiles/C++/api/syntaxdata.h");
    out.push_str("// Original header of the source file follows:\n//\n");
    for l in header.lines() {
        let _ = writeln!(out, "// {}", l.trim_end());
    }
    out.push_str("\n//! Keyword tables of the GAMS Studio syntax highlighter (`gams::studio::syntax::SyntaxData`).\n\n");
    out.push_str("#![allow(clippy::all)]\n\n");
    for t in &tables {
        let name = const_name(&t.func);
        let ty = if t.second_is_int {
            "&[(&str, i32)]"
        } else {
            "&[(&str, &str)]"
        };
        let _ = writeln!(
            out,
            "/// `SyntaxData::{}()` ({} entries)",
            t.func,
            t.entries.len()
        );
        let _ = writeln!(out, "pub const {name}: {ty} = &[");
        for (k, v) in &t.entries {
            match v {
                Value::Str(s) => {
                    let _ = writeln!(out, "    ({k:?}, {s:?}),");
                }
                Value::Int(i) => {
                    let _ = writeln!(out, "    ({k:?}, {i}),");
                }
            }
        }
        out.push_str("];\n\n");
    }
    out.push_str("/// Names of all tables in source order (function name, entry count).\n");
    out.push_str("pub const TABLES: &[(&str, usize)] = &[\n");
    for t in &tables {
        let _ = writeln!(out, "    ({:?}, {}),", t.func, t.entries.len());
    }
    out.push_str("];\n");

    std::fs::write(&output, out)
        .unwrap_or_else(|e| panic!("cannot write {}: {e}", output.display()));
    eprintln!("wrote {} tables to {}", tables.len(), output.display());
}
